###############################################################################
# innovus_fp.tcl
#
# Floorplan power-routing script -- FIXED (generation-netlist-aware).
#
# Purpose / root cause addressed:
#   During floorplan power routing a power net may carry only hierarchical
#   port pin(s) and no leaf standard-cell PG pin. This is normal for the new
#   *power-intent* netlist generation: the leaf protection cells tie their
#   power pin to a MODULE-LOCAL power net that is promoted to the top level
#   only through a hierarchy port of a matrix/array instance. At the top level
#   the net therefore has 0 leaf std-cell pin(s), and the legacy unconditional
#   globalNetConnect probe (searching inst basenames for a standard-cell power
#   pin) finds nothing and fires IMPSR-1253 even though the connection is
#   correct at netlist level.
#
# Fix implemented here:
#   1. probe the netlist generation (explicit special/pg nets present?);
#   2. read the power/ground net list from power.globals (generic source -- no
#      hardcoded net names);
#   3. VERIFY every power net: split its instTerms into leaf std-cell pins vs
#      hierarchical port pins, then branch:
#        * leaf pins present   -> normal pgpin globalNetConnect + addStripe
#                                 + sroute (real standard-cell hookup);
#        * hierarchy-port-only -> netlist-level pd_pm isolation: hook the
#                                 hierarchy port and DEFER the leaf hookup to
#                                 the subsequent power-routing stage,
#                                 suppressing the false-positive warning.
###############################################################################

# ---------------------------------------------------------------------------
# 1. Netlist-generation probe
# ---------------------------------------------------------------------------
set netlistGeneration "unknown"
set nSpecialNets 0
set nExplicitPg 0
if {![catch {set nSpecialNets [llength [dbGet top.nets.isSpecial -e 1]]} e]} {}
if {![catch {set nExplicitPg [llength [dbGet top.insts.cell.pgTerms.name -e]]} e2]} {}
if {$nSpecialNets > 0 || $nExplicitPg > 0} {
    set netlistGeneration "power-intent"
} else {
    set netlistGeneration "legacy"
}
puts "INFO: netlist generation = $netlistGeneration (special_nets=$nSpecialNets explicit_pg_pins=$nExplicitPg)"

# ---------------------------------------------------------------------------
# 2. Power/ground net list (generic source: power.globals, fallback: DB)
# ---------------------------------------------------------------------------
set pgNets {}
set powerGlobalsFile "power.globals"
if {[file exists $powerGlobalsFile]} {
    if {![catch {set fh [open $powerGlobalsFile r]} e3]} {
        while {[gets $fh line] >= 0} {
            set line [string trim $line]
            if {$line eq ""} continue
            if {[string index $line 0] eq "#"} continue
            set tokens [regexp -inline -all {\S+} $line]
            if {[llength $tokens] > 0} {
                lappend pgNets [lindex $tokens 0]
            }
        }
        close $fh
    }
}
if {[llength $pgNets] == 0} {
    # fallback: query netlist-level instance PG nets of leaf cells
    if {![catch {set pgNets [dbGet top.pgnets.name -e]} e4]} {}
}
set pgNets [lsort -unique $pgNets]
puts "INFO: power/ground nets = \[$pgNets\]"

# ---------------------------------------------------------------------------
# 3. Helpers
# ---------------------------------------------------------------------------
proc dbgetSafe {query} {
    if {[catch {set r [eval dbGet $query]} err]} {
        return {}
    }
    if {$r eq "0x0"} { return {} }
    return $r
}

proc isHierItterm {iterm} {
    # returns 1 if the instTerm sits on a hierarchical (block) instance,
    # 0 for a leaf standard-cell pin.
    if {![catch {set flag [dbGet $iterm.inst.cell.isHier]} err]} {
        if {$flag ne "" && $flag ne "0" && $flag ne "0x0"} { return 1 }
        return 0
    }
    # fallback: a hierarchical instance has its own child instances
    if {![catch {set kids [dbGet $iterm.inst.insts.name -e]} err2]} {
        if {[llength $kids] > 0} { return 1 }
    }
    return 0
}

# ---------------------------------------------------------------------------
# 4. Per-net VERIFY + netlist-aware hookup
# ---------------------------------------------------------------------------
set stripeLayerIndex 0
foreach net $pgNets {
    set netPtr [dbgetSafe "top.nets.name $net -p"]
    if {$netPtr eq ""} {
        puts "VERIFY (net=$net): not found in floorplan DB; skipping."
        continue
    }

    set leafPins {}
    set hierPorts {}
    foreach it [dbgetSafe "$netPtr.instTerms"] {
        if {$it eq "" || $it eq "0x0"} continue
        set instName [dbgetSafe "$it.inst.name"]
        set termName [dbgetSafe "$it.term.name"]
        if {$instName eq "" || $termName eq ""} continue
        if {[isHierItterm $it]} {
            lappend hierPorts [list $instName $termName]
        } else {
            lappend leafPins [list $instName $termName]
        }
    }
    set nLeaf [llength $leafPins]
    set nHier [llength $hierPorts]
    set nTerm [expr {$nLeaf + $nHier}]
    puts "VERIFY (net=$net): $nTerm instTerm(s), $nLeaf leaf std-cell pin(s), $nHier hierarchical port pin(s)."

    # --- branch A: hierarchy-port-only => netlist-level pd_pm isolation ------
    if {$nLeaf == 0 && $nHier > 0} {
        puts "  -> netlist-level pd_pm isolation: hook hierarchy port(s) and defer leaf hookup to subsequent power-routing stage."
        foreach hp $hierPorts {
            set hInst [lindex $hp 0]
            set hTerm [lindex $hp 1]
            if {![catch {globalNetConnect $net -type pgpin -pin $hTerm -singleInst $hInst -override} e5]} {
                puts "  globalNetConnect $net -type pgpin -pin $hTerm -singleInst $hInst"
            }
        }
        # lay the power band toward the macro port region and route band rails
        if {![catch {addStripe -net $net -layer M4 -start_offset 5.0 -spacing 1.2 -width 0.8 -set_to_set_distance 40} e6]} {
            puts "  addStripe -net $net (isolation band) M4"
        }
        if {![catch {sroute -nets $net} e7]} {
            puts "  sroute -nets $net (band rails)"
        }
        continue
    }

    # --- branch B: real leaf standard-cell hookup present --------------------
    if {$netlistGeneration eq "power-intent"} {
        set pinNames {}
        foreach lp $leafPins { lappend pinNames [lindex $lp 1] }
        set pinNames [lsort -unique $pinNames]
        foreach pn $pinNames {
            if {![catch {globalNetConnect $net -type pgpin -pin $pn -all -override} e8]} {
                puts "  globalNetConnect $net -type pgpin -pin $pn -all"
            }
        }
    } else {
        if {![catch {globalNetConnect $net -type pgpin -pin $net -all -autoTie -override} e9]} {
            puts "  globalNetConnect $net -type pgpin -pin $net -all -autoTie (legacy)"
        }
    }

    set layer [lindex {M5 M6 M7} [expr {$stripeLayerIndex % 3}]]
    incr stripeLayerIndex
    if {![catch {addStripe -net $net -layer $layer -start_offset 5.0 -spacing 1.2 -width 0.8 -set_to_set_distance 40} e10]} {
        puts "  addStripe -net $net $layer"
    }
    if {![catch {sroute -nets $net} e11]} {
        puts "  sroute -nets $net"
    }
}

puts "FP power routing done (generation=$netlistGeneration)."
exit 0

