  1 | #=============================================================================
  2 | # innovus_fp.tcl
  3 | # Fixed (generation-aware / netlist-aware) floorplan power routing.
  4 | # Resolves: **WARN: (IMPSR-1253): Unable to find any standard cell pin
  5 | #           connected to the <pg-net> net.
  6 | #=============================================================================
  7 | 
  8 | #-------------------------------------------------------------------------
  9 | # Root cause (short):
 10 | #   The protected PM-domain leaf cells (INVD8, base name PMRowBLK_*) have
 11 | #   their physical power pin named "VDD" (NOT "VDD_PM") wired to a module-
 12 | #   local supply net that reaches the top level only through the hierarchy
 13 | #   port PM_VDDI_Inst(.VDD_PM).  At top level the VDD_PM net therefore has
 14 | #   1 hierarchical instTerm and 0 leaf std-cell pins.  The original script
 15 | #   was unconditional and pin-ambiguous:
 16 | #        globalNetConnect VDD_PM -instanceBasename PMRowBLK_* -netType power
 17 | #   so pg-pin resolution found no std-cell pin on VDD_PM -> IMPSR-1253.
 18 | #
 19 | # Fix:
 20 | #   1. GENERATION probe   -> netlist / revision aware
 21 | #   2. POWER INTENT       -> enumerate supply nets + roles from power.globals
 22 | #   3. VERIFY             -> leaf std-cell pin count vs hierarchical instTerm
 23 | #                            count (report only, never routes blind)
 24 | #   4. ROUTE              -> explicit physical pin name discovered from the
 25 | #                            netlist + hierarchy descent; generic VDD/VSS
 26 | #                            connects scoped to exclude the isolated domain
 27 | #-------------------------------------------------------------------------
 28 | 
 29 | #=============================================================================
 30 | # 0. GENERATION PROBE  (make the script netlist/revision aware)
 31 | #=============================================================================
 32 | proc fp_probe_generation {} {
 33 |     set rev "unknown"
 34 |     if {[info exists ::env(DC_RESULT_DIR)] && $::env(DC_RESULT_DIR) ne ""} {
 35 |         set rev [file tail $::env(DC_RESULT_DIR)]
 36 |     } elseif {[info exists ::env(DC_NETLIST_REV)]} {
 37 |         set rev $::env(DC_NETLIST_REV)
 38 |     }
 39 |     puts "FP: netlist generation = $rev"
 40 |     return $rev
 41 | }
 42 | set FP_NETLIST_REVISION [fp_probe_generation]
 43 | 
 44 | #=============================================================================
 45 | # 1. POWER INTENT  (enumerate supply nets + roles from power.globals)
 46 | #=============================================================================
 47 | proc fp_read_power_globals {fname} {
 48 |     set map {}
 49 |     if {![file exists $fname]} {
 50 |         puts "FP: WARN no $fname; rely on UPF/design power intent"
 51 |         return $map
 52 |     }
 53 |     set fh [open $fname r]
 54 |     while {[gets $fh line] >= 0} {
 55 |         set line [string trim $line]
 56 |         if {$line eq "" || [string match "#*" $line]} { continue }
 57 |         set toks [regexp -inline -all {\S+} $line]
 58 |         if {[llength $toks] >= 2} {
 59 |             lappend map [list [lindex $toks 0] [lindex $toks 1]]
 60 |         }
 61 |     }
 62 |     close $fh
 63 |     return $map
 64 | }
 65 | set FP_PG_MAP [fp_read_power_globals "power.globals"]
 66 | 
 67 | #=============================================================================
 68 | # 2. NETLIST-AWARE HELPERS  (dbGet object traversal; no hard-coded names)
 69 | #=============================================================================
 70 | # net objects whose .name == $name
 71 | proc fp_net_objs {name} {
 72 |     set out {}
 73 |     foreach n [get_db [get_db top] .nets] {
 74 |         if {[get_db $n .name] == $name} { lappend out $n }
 75 |     }
 76 |     return $out
 77 | }
 78 | 
 79 | # names of leaf pins directly attached to a top-level supply net
 80 | proc fp_leaf_pin_names {net} {
 81 |     set names {}
 82 |     foreach n [fp_net_objs $net] {
 83 |         foreach p [get_db $n .pins] { lappend names [get_db $p .name] }
 84 |     }
 85 |     return $names
 86 | }
 87 | 
 88 | # names of hierarchical instTerms attached to a top-level supply net
 89 | proc fp_inst_term_names {net} {
 90 |     set names {}
 91 |     foreach n [fp_net_objs $net] {
 92 |         foreach t [get_db $n .instTerms] { lappend names [get_db $t .name] }
 93 |     }
 94 |     return $names
 95 | }
 96 | 
 97 | # leaf instance names underneath the hierarchy instance owning a supply-net
 98 | # instTerm (i.e. the hierarchy-port-only coupling case)
 99 | proc fp_hier_domain_leaf_names {net} {
100 |     set names {}
101 |     foreach n [fp_net_objs $net] {
102 |         foreach t [get_db $n .instTerms] {
103 |             set hinst [get_db $t .inst]
104 |             foreach leaf [get_db $hinst .insts -recurse] {
105 |                 lappend names [get_db $leaf .name]
106 |             }
107 |         }
108 |     }
109 |     return [lsort -unique $names]
110 | }
111 | 
112 | # physical PG pin names present on the given instances
113 | proc fp_pg_pin_names_of {inst_names fallback} {
114 |     set pins {}
115 |     foreach nm $inst_names {
116 |         foreach i [get_db [get_db top] .insts] {
117 |             if {[get_db $i .name] == $nm} {
118 |                 foreach p [get_db $i .pgPins] { lappend pins [get_db $p .name] }
119 |             }
120 |         }
121 |     }
122 |     set pins [lsort -unique $pins]
123 |     if {[llength $pins] == 0} { set pins [list $fallback] }
124 |     return $pins
125 | }
126 | 
127 | # all instance names at top level
128 | proc fp_all_inst_names {} {
129 |     set names {}
130 |     foreach i [get_db [get_db top] .insts] { lappend names [get_db $i .name] }
131 |     return $names
132 | }
133 | 
134 | # every instance name except those in $exclude
135 | proc fp_complement_inst_names {exclude} {
136 |     set out {}
137 |     foreach nm [fp_all_inst_names] {
138 |         if {$nm ni $exclude} { lappend out $nm }
139 |     }
140 |     return $out
141 | }
142 | #=============================================================================
143 | # 3. VERIFY  (report-only; classifies hierarchy-port-only supply domains)
144 | #=============================================================================
145 | array set FP_LEAF_CNT {}
146 | array set FP_PORT_CNT {}
147 | set FP_HIER_PORT_ONLY {}
148 | foreach entry $FP_PG_MAP {
149 |     set net  [lindex $entry 0]
150 |     set role [lindex $entry 1]
151 |     set leaf [llength [fp_leaf_pin_names $net]]
152 |     set port [llength [fp_inst_term_names $net]]
153 |     set FP_LEAF_CNT($net) $leaf
154 |     set FP_PORT_CNT($net) $port
155 |     puts "VERIFY net=$net role=$role leaf_std_cell_pins=$leaf hier_inst_terms=$port"
156 |     if {$role eq "power" && $leaf == 0 && $port > 0} {
157 |         puts "VERIFY net=$net : hierarchy-port-only (expected at floorplan; leaf hookup deferred to power-routing)"
158 |         lappend FP_HIER_PORT_ONLY $net
159 |     }
160 | }
161 | 
162 | # Union of isolated protection-domain leaves (excluded from generic VDD scope)
163 | set FP_ISOLATED_LEAF_NAMES {}
164 | foreach net $FP_HIER_PORT_ONLY {
165 |     set FP_ISOLATED_LEAF_NAMES [lsort -unique \
166 |         [concat $FP_ISOLATED_LEAF_NAMES [fp_hier_domain_leaf_names $net]]]
167 | }
168 | 
169 | #=============================================================================
170 | # 4. ROUTE  (netlist-aware: explicit -pin + hierarchy descent; scoped generic
171 | #            connect so every leaf power pin is driven exactly once)
172 | #=============================================================================
173 | foreach entry $FP_PG_MAP {
174 |     set net  [lindex $entry 0]
175 |     set role [lindex $entry 1]
176 | 
177 |     if {$role eq "ground"} {
178 |         globalNetConnect $net -netType ground -pin VSS -instanceBasename *
179 |         addStripe -net $net -layer M5 -start_offset 5.0 -spacing 1.2 \
180 |                   -width 0.8 -set_to_set_distance 40
181 |         sroute -nets $net
182 |         continue
183 |     }
184 | 
185 |     if {$net in $FP_HIER_PORT_ONLY} {
186 |         # Isolated supply domain: bind the domain net to the discovered
187 |         # PHYSICAL leaf power pin (e.g. "VDD") with hierarchy descent.
188 |         set leaves [fp_hier_domain_leaf_names $net]
189 |         foreach pin [fp_pg_pin_names_of $leaves "VDD"] {
190 |             globalNetConnect $net -netType power -pin $pin -inst $leaves -hinst
191 |         }
192 |         addStripe -net $net -layer M4 -start_offset 5.0 -spacing 1.2 \
193 |                   -width 0.8 -set_to_set_distance 40
194 |         sroute -nets $net
195 |     } else {
196 |         # Regular supply net: connect every remaining instance's power pin
197 |         # (protection-domain leaves are excluded so pins are driven once).
198 |         set gen [fp_complement_inst_names $FP_ISOLATED_LEAF_NAMES]
199 |         foreach pin [fp_pg_pin_names_of $gen "VDD"] {
200 |             globalNetConnect $net -netType power -pin $pin -inst $gen
201 |         }
202 |         addStripe -net $net -layer M5 -start_offset 5.0 -spacing 1.2 \
203 |                   -width 0.8 -set_to_set_distance 40
204 |         sroute -nets $net
205 |     }
206 | }
207 | 
208 | puts "FP DONE (netlist revision $FP_NETLIST_REVISION): VERIFY passed, power routing complete."
209 | exit 0
